class Solution {
public:
    int numMatchingSubseq(string s, vector<string>& words) {
        vector<int> pos[26];
        for (int i = 0; i < (int)s.length(); i++) {
            pos[s[i] - 'a'].push_back(i);
        }
        int ans = 0;
        unordered_map<string, bool> memo;
        for (const string& w : words) {
            if (memo.count(w)) {
                if (memo[w]) ans++;
                continue;
            }
            int idx = -1;
            bool match = true;
            for (char ch : w) {
                const auto& vec = pos[ch - 'a'];
                auto it = upper_bound(vec.begin(), vec.end(), idx);
                if (it == vec.end()) {
                    match = false;
                    break;
                }
                idx = *it;
            }
            memo[w] = match;
            if (match) ans++;
        }
        return ans;
    }
};

class Solution {
    public int numMatchingSubseq(String s, String[] words) {
        List<Integer>[] pos = new ArrayList[26];
        for (int i = 0; i < 26; i++) pos[i] = new ArrayList<>();
        for (int i = 0; i < s.length(); i++) {
            pos[s.charAt(i) - 'a'].add(i);
        }
        int ans = 0;
        Map<String, Boolean> memo = new HashMap<>();
        for (String w : words) {
            if (memo.containsKey(w)) {
                if (memo.get(w)) ans++;
                continue;
            }
            int idx = -1;
            boolean match = true;
            for (int i = 0; i < w.length(); i++) {
                List<Integer> list = pos[w.charAt(i) - 'a'];
                int posIdx = Collections.binarySearch(list, idx + 1);
                if (posIdx < 0) posIdx = -posIdx - 1;
                if (posIdx >= list.size()) {
                    match = false;
                    break;
                }
                idx = list.get(posIdx);
            }
            memo.put(w, match);
            if (match) ans++;
        }
        return ans;
    }
}

var numMatchingSubseq = function(s, words) {
    const pos = Array.from({ length: 26 }, () => []);
    for (let i = 0; i < s.length; i++) {
        pos[s.charCodeAt(i) - 97].push(i);
    }
    let ans = 0;
    const memo = new Map();
    for (const w of words) {
        if (memo.has(w)) {
            if (memo.get(w)) ans++;
            continue;
        }
        let idx = -1;
        let match = true;
        for (let i = 0; i < w.length; i++) {
            const arr = pos[w.charCodeAt(i) - 97];
            let low = 0, high = arr.length;
            while (low < high) {
                const mid = (low + high) >> 1;
                if (arr[mid] > idx) high = mid;
                else low = mid + 1;
            }
            if (low === arr.length) {
                match = false;
                break;
            }
            idx = arr[low];
        }
        memo.set(w, match);
        if (match) ans++;
    }
    return ans;
};
